function Squrare({ value }) {
  function handleClick() {
    console.log("clicked!");
  }
  return (
    <button className="square" onClick={handleClick}>
      {value}
    </button>
  );
}

export default function board() {
  return (
    <>
      <div className="board-row">
        <Squrare value="1" />
        <Squrare value="2" />
        <Squrare value="3" />
      </div>
      <div className="board-row">
        <Squrare value="4" />
        <Squrare value="5" />
        <Squrare value="6" />
      </div>
      <div className="board-row">
        <Squrare value="7" />
        <Squrare value="8" />
        <Squrare value="9" />
      </div>
    </>
  );
}
